#!/usr/bin/env python3
"""Turn 35 Wave 39: 12th Man = community vote for the final Dream Star (OFFICIAL App Store notes) with the winner never named; full coach point model (+1/+2/+3 stats), GK coach GKR>GKH rule, coach gem prices and per-point economics, Special Coach choose-from-two mechanic + the Legendary-scout cancellation trick, STR/CON x2 weighting, Dream Star Agents, English League Classics in the Prize Ladder, iOS Game Centre leaderboards."""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w39')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="official"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid
def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid
os.makedirs(RAW_DIR,exist_ok=True)

# ---------- EV-438: 12th Man resolved ----------
e_12=new_ev("App Store US/FM DLS26 version history (v13.100 26 Feb 2026, v13.110 2 Mar 2026, v13.120 25 Mar 2026, v13.130 27 Mar 2026), APKMirror v13.100/13.110 release notes, official FTG TikTok (@dreamleaguesoccer.ftg), thesoccerera, dlskits.mobi, mokoweb",
    "THE 12TH MAN IS RESOLVED AS A DREAM STARS MECHANIC. The official App Store version history gives the full arc: v13.100 (26 Feb 2026) and v13.110 (2 Mar 2026) both list '12th Man Vote - Pick the final Dream Star with the DLS community!' alongside 'Dream Stars 26 - Coming soon! The season's top performers, with enhanced attributes.' v13.120 (25 Mar 2026) then lists '12th Man - The DLS community has voted, and we've added this extra superstar to the collection', and v13.130 (27 Mar 2026) ships 'Dream Stars 2026 - Boosted players, featuring those who have had huge performances this season.' So the 12th Man is the COMMUNITY-VOTED FINAL DREAM STAR: FTG publishes the Dream Stars squad from real-world season performances, opens a community vote for one extra slot, and adds the winner to the collection. The official TikTok promoted it as 'From the spot, outside the box, in the air. He will score them all. Your #DreamStars 12th Man.' DREAM STARS ARE OBTAINED VIA DREAM STAR AGENTS - the official TikTok ran a countdown 'There's only 1 week left to get Dream Stars 26 via Dream Star Agents.' CRITICAL LIMIT: FTG never names the winning 12th Man in any store note, TikTok caption, or community source, so the IDENTITY gap persists even though the MECHANIC is now fully closed. A separate, possibly unrelated use of the term exists in the v13.430 Cult Heroes datamine, where Vozinha (GK, 83, Cape Verde) is annotated '(12th Man)' - this is most likely a CARD TYPE label on the weakest Cult Hero rather than the Dream Stars vote winner, and the two must not be conflated. Also captured from the same version history: the Winter Reload update ran v13.100-v13.120 (26 Feb - 25 Mar 2026) and included a News System, major Clan improvements (leaderboards, vice-captains, clan point boosts), UI and SFX upgrades, and iOS GAME CENTRE support with achievements and friend leaderboards - the last of these is directly relevant to defining '#1'.",
    "evidence/raw/turn35_w39/EV-438_12th_man.html",
    "12TH MAN RESOLVED: it is the community-voted FINAL DREAM STAR. Official version history: v13.100 (26 Feb 2026) and v13.110 (2 Mar) list '12th Man Vote - Pick the final Dream Star with the DLS community!'; v13.120 (25 Mar) lists '12th Man - The DLS community has voted, and we've added this extra superstar to the collection'; v13.130 (27 Mar) ships Dream Stars 2026. FTG publishes Dream Stars from real-world season performances and opens one community slot. Dream Stars are obtained via DREAM STAR AGENTS. FTG never names the winner, so the identity gap persists while the mechanic is closed. Vozinha's '(12th Man)' label in the Cult Heroes datamine is probably a CARD TYPE, not the vote winner - do not conflate. Also: Winter Reload = v13.100-v13.120 (26 Feb-25 Mar 2026) with News System, Clan leaderboards/vice-captains/clan point boosts, UI+SFX, and iOS GAME CENTRE support with achievements and FRIEND LEADERBOARDS",
    quality="official")

add_claim("The 12th Man is the community-voted final Dream Star: FTG publishes the Dream Stars squad from real-world season performances and opens a community vote for one additional slot, then adds the winner to the collection.", 1, "12thman/mechanic-dream-star-vote", [e_12], notes="Gap CLOSED on the mechanic")
add_claim("Official timeline: the 12th Man Vote shipped in v13.100 (26 Feb 2026) and v13.110 (2 Mar 2026), the voted winner was added in v13.120 (25 Mar 2026), and Dream Stars 2026 shipped in v13.130 (27 Mar 2026).", 1, "12thman/version-timeline", [e_12])
add_claim("Dream Stars are obtained through Dream Star Agents, per the official FTG TikTok countdown.", 1, "cards/dream-star-agents", [e_12])
add_claim("FTG has never named the winning 12th Man in any store note, TikTok caption or community source - the IDENTITY gap persists even though the mechanic is closed.", 2, "12thman/identity-never-published", [e_12])
add_claim("Vozinha (GK, 83, Cape Verde) carries a '(12th Man)' annotation in the v13.430 Cult Heroes datamine; this is most likely a CARD TYPE label on the weakest Cult Hero rather than the Dream Stars vote winner, and the two must not be conflated.", 3, "12thman/vozinha-label-ambiguity", [e_12], notes="Two distinct uses of the term '12th Man'")
add_claim("iOS Game Centre support was added in the Winter Reload update, giving achievements and FRIEND LEADERBOARDS on iOS - the closest thing to a wider ranking surface than the regional DLL leaderboard.", 1, "dll/ios-game-centre-leaderboards", [e_12])
add_claim("English League Classics are four top English-game stars available in the Prize Ladder, per the official FTG TikTok.", 1, "prizeladder/english-league-classics", [e_12])

# ---------- EV-439: coach point model + special coaches ----------
e_cp2=new_ev("r/DreamLeagueSoccer 1abrrl5 (Apr 2024 beginners guide to coaching), 1dqq9e (Jan 2024 DLS24 beginners guide), 1en4rl1 (Aug 2024), 1qbkdkl (Jan 2026), 1emifpy (Aug 2024), 1hmsicn (Dec 2024), 1hnll1u (Dec 2024), 1b4ovuj (Mar 2024), 1h84j6p (Dec 2024 special coaches), 1sgo3gd (Apr 2026 special coach method), 1u69y7v (Jun 2026 maxed Desailly), 1anj3rf (coaching point system), 1aioi6e (Feb 2024), 1ajd6pu (Feb 2024 coaching math), 1i3f2jv (Jan 2025), LevelWinner DLS20 Training Guide, gamingonphone DLS26 career guide",
    "COACH POINT MODEL AND ECONOMICS. POINT DELIVERY: a Common coach boosts 1 random stat by +1; a Rare coach boosts 2 random stats by +2 each; a Legendary coach boosts 3 random stats by +3 each. Goalkeeping coaches affect ONLY GKR and GKH - Legendary +3 to both, Rare +2 to one, Common +1 to one - and the explicit rule is to use a Legendary GK coach ONLY IF GKR > GKH, which independently corroborates the GKR >= GKH balance rule. GEM PRICES: Common 17 gems, Rare 52 gems, Legendary 157 gems (at a maxed Training facility). PER-POINT ECONOMICS: a Legendary fitness coach gives 27 points for 157 gems = 5.8 gems per point, versus 26.25 gems per point for a Legendary SPECIAL coach - special coaches are roughly 4.5x worse value. A Rare coach gives +8 points for 1,535 coins = about 192 coins per point, which is why 80-rated defenders at 1,535 coins are the cheapest Rare-coach source. Head-to-head: for 225 gems a Legendary coach gives +27 points while Rare coaches give +24, so Legendary wins on raw points but Rare wins on controllability. PLAYER CAPACITY: each player has roughly 80-81 upgrade points before maxing (about 90 Common coaches for a fully maxed card), each Overall point corresponds to about 8 stat points, and STRENGTH and CONTROL count as x2 for most positions except wingers - so 3 points of strength counts as 6. RELEASE YIELDS: releasing a legendary player gives 2 Rare coaches, worth about 16 attribute points, so the maths is 1,535 / 8 = 192 coins per point. BUILD TIME: one player reports a 21-player squad plus GK plus a special player took about half a year. BREAKTHROUGH: the DLS20 baseline is Common 5%, Rare 10%, Legendary 20% Breakout Rating, and the consensus is that rarity affects ONLY the breakthrough chance, never the maximum potential - 'if you get a breakthrough, points are added. The higher rarity just increases breakthrough chance, that's all.' SPECIAL COACHES: these are the only coaches where the manager CHOOSES the upgraded stat - the game presents 2 randomised stat options (one fitness, one technical) and you pick one. Prices are Common 63 gems / 2 points (31.5 gems per point), Rare 168 gems / 6 points (28 gems per point) and Legendary 280 gems / 12 points (23.33 gems per point). Maxing one special player needs about 7.5 Legendary Special Coaches = roughly 2,100 gems (or 15 Rares = 2,520 gems), with one source claiming 2,100-2,835 gems and another 6-7 coaches - a minor conflict. THE LEGENDARY SCOUT TRICK: keep at least one Legendary Special coach because it reveals the NEXT FOUR upgradable stats, and you can CANCEL and use a different coach without consuming it. THE CLEARING METHOD: use Legendary Special coaches first and inspect the first three stats; if all are desirable follow with Rares; if unwanted stats appear (tackling for strikers, strength for wingers) use COMMON Special coaches to clear them because commons add fewer points, then switch back to Rare or Legendary and repeat. Alternative advice: always use a Common coach if at least one of the offered stats is not what you want.",
    "evidence/raw/turn35_w39/EV-439_coach_point_model.html",
    "COACH POINT MODEL: Common +1 stat/+1, Rare +2 stats/+2 each, Legendary +3 stats/+3 each. Goalkeeping coaches touch ONLY GKR and GKH (Legendary +3 both, Rare +2 one, Common +1 one) and a Legendary GK coach should be used ONLY IF GKR > GKH. Gem prices: Common 17g, Rare 52g, Legendary 157g at maxed Training. Legendary fitness = 27 points for 157g = 5.8 gems/point vs 26.25 gems/point for a Legendary SPECIAL coach. Rare coach = +8 points for 1,535 coins = 192 coins/point (why 80-rated defenders are the cheapest rare source). 225 gems: Legendary +27 vs Rare +24 - Legendary wins points, Rare wins control. Each player has ~80-81 upgrade points (~90 commons to max), ~8 stat points per OVR point, and STRENGTH and CONTROL count as x2 for most positions except wingers. Releasing a legendary player gives 2 rare coaches = ~16 points, so 1,535/8 = 192 coins per point. A 23-man squad took ~6 months. Breakthrough DLS20 baseline 5/10/20% and rarity affects ONLY the breakthrough chance, never the cap. SPECIAL COACHES: the ONLY coaches where you CHOOSE the stat - 2 randomised options (one fitness, one technical), pick one. Prices Common 63g/2pts, Rare 168g/6pts, Legendary 280g/12pts. Maxing a special player ~7.5 Legendary Special Coaches = ~2,100 gems (conflict: 6-7 coaches, or 2,100-2,835 gems). LEGENDARY SCOUT TRICK: keep one Legendary Special coach to reveal the next 4 upgradable stats and cancel without consuming it. CLEARING METHOD: legendary first, rare if the three stats are desirable, common to clear unwanted stats, then repeat",
    quality="community")

add_claim("Coach point delivery: a Common coach boosts 1 random stat by +1, a Rare coach boosts 2 random stats by +2 each, and a Legendary coach boosts 3 random stats by +3 each.", 2, "training/coach-point-delivery", [e_cp2])
add_claim("Goalkeeping coaches affect ONLY GKR and GKH - Legendary +3 to both, Rare +2 to one, Common +1 to one - and a Legendary GK coach should be used only if GKR > GKH, independently corroborating the GKR >= GKH balance rule.", 2, "training/gk-coach-rules", [e_cp2])
add_claim("Coach gem prices at a maxed Training facility: Common 17 gems, Rare 52 gems, Legendary 157 gems.", 3, "training/coach-gem-prices", [e_cp2])
add_claim("Per-point economics: a Legendary fitness coach gives 27 points for 157 gems (5.8 gems per point) versus 26.25 gems per point for a Legendary Special Coach - special coaches are roughly 4.5x worse value.", 2, "training/gems-per-point", [e_cp2])
add_claim("A Rare coach gives +8 points for 1,535 coins, about 192 coins per point, which is why 80-rated defenders at 1,535 coins are the cheapest Rare-coach source in the game.", 2, "training/rare-coach-coin-economics", [e_cp2])
add_claim("Head-to-head for 225 gems: a Legendary coach gives +27 points while Rare coaches give +24, so Legendary wins on raw points but Rare wins on controllability.", 3, "training/legendary-vs-rare-tradeoff", [e_cp2])
add_claim("Each player has roughly 80-81 upgrade points before maxing (about 90 Common coaches for a fully maxed card), each Overall point corresponds to about 8 stat points, and STRENGTH and CONTROL count as x2 for most positions except wingers.", 3, "training/player-upgrade-capacity", [e_cp2])
add_claim("Releasing a legendary player yields 2 Rare coaches worth about 16 attribute points, giving the 1,535 / 8 = 192 coins-per-point maths that drives the coach-farming rule.", 3, "economy/release-yield-maths", [e_cp2])
add_claim("Building a full 23-man squad (21 outfield plus GK plus a special player) took one player about half a year of play.", 3, "career/squad-build-time", [e_cp2])
add_claim("Special Coaches are the ONLY coaches where the manager chooses the upgraded stat: the game presents 2 randomised options (one fitness, one technical) and you pick one.", 2, "training/special-coach-choice", [e_cp2])
add_claim("Special Coach prices and value: Common 63 gems / 2 points (31.5 gems per point), Rare 168 gems / 6 points (28 gems per point), Legendary 280 gems / 12 points (23.33 gems per point).", 2, "training/special-coach-prices", [e_cp2])
add_claim("Maxing one special player needs about 7.5 Legendary Special Coaches, roughly 2,100 gems (or 15 Rares at 2,520 gems); one source claims 2,100-2,835 gems and another 6-7 coaches.", 3, "training/special-player-max-cost", [e_cp2], notes="C-020 candidate")
add_claim("LEGENDARY SCOUT TRICK: keep at least one Legendary Special coach because it reveals the next FOUR upgradable stats, and you can cancel and use a different coach without consuming it.", 2, "training/legendary-scout-trick", [e_cp2])
add_claim("Special Coach clearing method: use Legendary Special coaches first and inspect the first three stats; if all are desirable follow with Rares; if unwanted stats appear (tackling for strikers, strength for wingers) use Common Special coaches to clear them because commons add fewer points, then switch back to Rare or Legendary and repeat.", 2, "training/special-coach-clearing-method", [e_cp2])
add_claim("Alternative Special Coach rule: always use a Common coach if at least one of the two offered stats is not what you want.", 3, "training/special-coach-common-if-unwanted", [e_cp2])

p=os.path.join(RAW_DIR,'EV-438_12th_man.html')
